""" Binary Search takes array and value to search """
def binary_search(arr: Any, value: Any) -> object {
    """ returns index or-1""";
    count = len(arr);
    midpoint = count // 2;
    start_index = 0;
    end_index = count - 1;
    while ((value != arr[(start_index + midpoint)]) and (count > 1)) {
        if (value > arr[(midpoint + start_index)]) {
            start_index = midpoint;
            count = count - midpoint;
            midpoint = count // 2;
        } else {
            end_index = end_index - midpoint;
            count = count - midpoint;
            midpoint = count // 2;
        }
    }
    if (value == arr[(midpoint + start_index)]) {
        return (midpoint + start_index);
    } else {
        return -1;
    }
}

"""
    Hill equation
    :param val: input value
    :param diss_cf: dissociation coefficient
    :param hill_cf: Hill coefficient
    :return: Hill equation for input *val*
    """
def hill_equation(val: Any, diss_cf: Any, hill_cf: Any) -> object {
    if (val == 0) {
        return 0;
    } else {
        return (1 / (1 + ((diss_cf / val) ** hill_cf)));
    }
}

